arguments.command:
cd /tmp && git -C /app show HEAD:src/lib/slots.sh >/dev/null; cat > /tmp/ov.sh <<'E'
to_min() { :; }
overlaps() { [ "$1" -lt "$3" ] && [ "$3" -lt "$2" ]; }
t(){ overlaps "$@" && echo "overlap: $*" || echo "NO overlap: $*"; }
t 630 700 600 660   # new starts earlier, partially overlaps
t 600 660 600 660   # identical
t 630 650 600 720   # new contains existing
E
bash /tmp/ov.sh; gh auth status 2>&1 | grep -i account

